// Protection against sudden volume changes: Connections { target: sink?.audio ?? null; function onVolumeChanged() }
o2->setConnector([=, this](Object* object, std::vector<Connection>& out) {
  if (object == nullptr) {
    return;
  }
  auto* target = static_cast<qs::PwNodeAudio*>(object);
  out.push_back(target->volume.changed().connect([=, this]() {
    auto* protection = ::ii::common::Config::instance().options->audio.get()->protection.get();
    if (!protection->enable.get()) {
      return;
    }
    const double newVolume = sink.get()->audio.get()->volume.get();
    // when resuming from suspend, we should not write volume to avoid pipewire volume reset issues
    // (a number is never undefined or null: of the three tests only isNaN can hold)
    if (std::isnan(newVolume)) {
      o2->lastReady.set(false);
      o2->lastVolume.set(0);
      return;
    }
    if (!o2->lastReady.get()) {
      o2->lastVolume.set(newVolume);
      o2->lastReady.set(true);
      return;
    }
    const double maxAllowedIncrease = protection->maxAllowedIncrease.get() / 100;
    const double maxAllowed = protection->maxAllowed.get() / 100;

    if (newVolume - o2->lastVolume.get() > maxAllowedIncrease) {
      sink.get()->audio.get()->volume.set(o2->lastVolume.get());
      sinkProtectionTriggered.emit(::ii::services::Translation::instance().tr("Illegal increment"));
    } else if (newVolume > maxAllowed || newVolume > hardMaxValue.get()) {
      sinkProtectionTriggered.emit(::ii::services::Translation::instance().tr("Exceeded max allowed"));
      // std::min(a, b) returns a when either is NaN; only lastVolume can be NaN here, as with Math.min
      sink.get()->audio.get()->volume.set(std::min(o2->lastVolume.get(), maxAllowed));
    }
    o2->lastVolume.set(sink.get()->audio.get()->volume.get());
  }));
});

